import { SearchIcon } from 'lucide-react';
import { useEffect, useMemo, useRef, useState } from 'react';
import { formatPrice } from '../../format';
import type { Quote } from '../../types';
import { cn } from '../../utils';
import { Dialog, DialogContent, DialogDescription, DialogTitle } from '../ui/dialog';
import { Delta } from './delta';

export interface SymbolSearchProps {
  quotes: Quote[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSelect: (quote: Quote) => void;
  /** Shown above the results before anything is typed. */
  recent?: string[];
  placeholder?: string;
  pricePrecision?: number;
}

/**
 * Instrument search, as a command palette.
 *
 * Ranked rather than filtered alphabetically: an exact ticker match outranks a
 * prefix, which outranks a hit in the company name. Typing "A" should offer
 * AAPL before Alphabet, because on a trading desk the ticker is the name.
 */
function score(quote: Quote, query: string): number {
  const q = query.toLowerCase();
  const symbol = quote.symbol.toLowerCase();
  const name = (quote.name ?? '').toLowerCase();
  if (symbol === q) return 100;
  if (symbol.startsWith(q)) return 80 - symbol.length;
  if (name.startsWith(q)) return 60 - name.length / 10;
  if (symbol.includes(q)) return 40;
  if (name.includes(q)) return 20;
  return -1;
}

export function SymbolSearch({
  quotes,
  open,
  onOpenChange,
  onSelect,
  recent = [],
  placeholder = 'Search symbol or company…',
  pricePrecision = 2,
}: SymbolSearchProps) {
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(0);
  const listRef = useRef<HTMLDivElement | null>(null);

  const results = useMemo(() => {
    if (!query.trim()) {
      const pinned = recent
        .map((s) => quotes.find((q) => q.symbol === s))
        .filter((q): q is Quote => !!q);
      return pinned.length ? pinned : quotes.slice(0, 8);
    }
    return quotes
      .map((q) => ({ quote: q, s: score(q, query.trim()) }))
      .filter((r) => r.s >= 0)
      .sort((a, b) => b.s - a.s)
      .slice(0, 10)
      .map((r) => r.quote);
  }, [quotes, query, recent]);

  // A changing result set must never leave the highlight pointing past the end.
  useEffect(() => setActive(0), [query]);
  useEffect(() => {
    if (!open) setQuery('');
  }, [open]);

  useEffect(() => {
    listRef.current
      ?.querySelector<HTMLElement>(`[data-index="${active}"]`)
      ?.scrollIntoView({ block: 'nearest' });
  }, [active]);

  const commit = (quote: Quote) => {
    onSelect(quote);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent showCloseButton={false} className="gap-0 overflow-hidden p-0 sm:max-w-lg">
        <DialogTitle className="sr-only">Search instruments</DialogTitle>
        <DialogDescription className="sr-only">
          Type to filter, arrow keys to move, enter to select.
        </DialogDescription>

        <div className="flex items-center gap-2.5 border-b px-3.5">
          <SearchIcon className="text-muted-foreground size-4 shrink-0" />
          <input
            autoFocus
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={placeholder}
            aria-label="Search instruments"
            aria-activedescendant={results[active] ? `sym-${results[active].symbol}` : undefined}
            className="placeholder:text-muted-foreground/70 h-12 w-full bg-transparent text-sm outline-none"
            onKeyDown={(e) => {
              if (e.key === 'ArrowDown') {
                e.preventDefault();
                setActive((i) => (i + 1) % Math.max(1, results.length));
              } else if (e.key === 'ArrowUp') {
                e.preventDefault();
                setActive((i) => (i - 1 + results.length) % Math.max(1, results.length));
              } else if (e.key === 'Enter' && results[active]) {
                e.preventDefault();
                commit(results[active]);
              }
            }}
          />
        </div>

        <div ref={listRef} role="listbox" aria-label="Results" className="max-h-80 overflow-y-auto p-1.5">
          {results.length === 0 && (
            <p className="text-muted-foreground px-3 py-6 text-center text-xs">
              Nothing matches “{query}”.
            </p>
          )}
          {results.map((quote, i) => {
            const change = quote.last - quote.prevClose;
            return (
              <button
                key={quote.symbol}
                id={`sym-${quote.symbol}`}
                data-index={i}
                role="option"
                aria-selected={i === active}
                type="button"
                onMouseEnter={() => setActive(i)}
                onClick={() => commit(quote)}
                className={cn(
                  'flex w-full cursor-pointer items-center gap-3 rounded-md px-2.5 py-2 text-left',
                  i === active && 'bg-accent',
                )}
              >
                <span className="w-16 shrink-0 font-mono text-xs font-semibold">
                  {quote.symbol}
                </span>
                <span className="text-muted-foreground min-w-0 flex-1 truncate text-xs">
                  {quote.name}
                </span>
                <span className="font-mono text-xs tabular-nums">
                  {formatPrice(quote.last, pricePrecision)}
                </span>
                <Delta percent={change / quote.prevClose} icon={false} className="w-16 justify-end" />
              </button>
            );
          })}
        </div>

        <div className="text-muted-foreground bg-muted flex items-center gap-3 border-t px-3.5 py-2 text-[10px]">
          <Key>↑</Key>
          <Key>↓</Key>
          <span>navigate</span>
          <Key>↵</Key>
          <span>select</span>
          <Key>esc</Key>
          <span>close</span>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function Key({ children }: { children: React.ReactNode }) {
  return (
    <kbd className="border-border bg-card text-foreground rounded border px-1.5 py-0.5 font-mono text-[10px]">
      {children}
    </kbd>
  );
}

import { TrendingDownIcon, TrendingUpIcon } from 'lucide-react';
import { directionOf, formatPercent, formatSigned } from '../../format';
import { cn } from '../../utils';
import { Badge } from '../ui/badge';

export interface DeltaProps {
  /** Absolute change. Omit to show the percentage alone. */
  value?: number;
  /** Change as a ratio (0.0421 renders as +4.21%). */
  percent?: number;
  precision?: number;
  /** Boxed badge instead of bare text. */
  pill?: boolean;
  /** Prefix with a trend icon. */
  icon?: boolean;
  className?: string;
}

/**
 * The change indicator.
 *
 * Direction is carried three ways at once - color, an icon, and an explicit
 * sign. Color alone fails a colorblind reader; in a grayscale screenshot or a
 * printed risk report it fails everyone.
 */
export function Delta({
  value,
  percent,
  precision = 2,
  pill = false,
  icon = true,
  className,
}: DeltaProps) {
  const basis = value ?? percent ?? 0;
  const direction = directionOf(basis);

  const parts: string[] = [];
  if (value !== undefined) parts.push(formatSigned(value, precision));
  if (percent !== undefined) {
    parts.push(
      value !== undefined
        ? `(${formatPercent(percent, precision, false)})`
        : formatPercent(percent, precision),
    );
  }

  const Icon =
    direction === 'up' ? TrendingUpIcon : direction === 'down' ? TrendingDownIcon : null;
  const tone = direction === 'up' ? 'text-up' : direction === 'down' ? 'text-down' : 'text-flat';

  const body = (
    <>
      {icon && Icon && <Icon className="size-3 shrink-0" aria-hidden="true" />}
      <span className="sr-only">
        {direction === 'up' ? 'up' : direction === 'down' ? 'down' : 'unchanged'}{' '}
      </span>
      {parts.join(' ')}
    </>
  );

  if (pill) {
    return (
      <Badge variant={direction} className={cn('font-mono tabular-nums', className)}>
        {body}
      </Badge>
    );
  }

  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 font-mono text-xs font-semibold tabular-nums whitespace-nowrap',
        tone,
        className,
      )}
    >
      {body}
    </span>
  );
}

import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import type { ComponentProps } from 'react';
import { cn } from '../../utils';

const badgeVariants = cva(
  "inline-flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-md border px-1.5 py-0.5 text-[10px] font-semibold tracking-wide whitespace-nowrap [&>svg]:pointer-events-none [&>svg:not([class*='size-'])]:size-3",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground border-transparent',
        secondary: 'bg-secondary text-secondary-foreground border-transparent',
        outline: 'text-foreground',
        up: 'bg-up-muted text-up border-transparent',
        down: 'bg-down-muted text-down border-transparent',
        flat: 'bg-muted text-flat border-transparent',
      },
    },
    defaultVariants: { variant: 'default' },
  },
);

function Badge({
  className,
  variant,
  asChild = false,
  ...props
}: ComponentProps<'span'> & VariantProps<typeof badgeVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : 'span';
  return (
    <Comp data-slot="badge" className={cn(badgeVariants({ variant }), className)} {...props} />
  );
}

export { Badge, badgeVariants };

import * as DialogPrimitive from '@radix-ui/react-dialog';
import { XIcon } from 'lucide-react';
import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/**
 * Radix Dialog. The order ticket uses it for the confirm step, where focus
 * trapping and a correctly labelled modal are not optional.
 */
const Dialog = DialogPrimitive.Root;
const DialogTrigger = DialogPrimitive.Trigger;
const DialogClose = DialogPrimitive.Close;
const DialogPortal = DialogPrimitive.Portal;

function DialogOverlay({ className, ...props }: ComponentProps<typeof DialogPrimitive.Overlay>) {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn(
        'data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 fixed inset-0 z-50 bg-black/60',
        className,
      )}
      {...props}
    />
  );
}

function DialogContent({
  className,
  children,
  showCloseButton = true,
  ...props
}: ComponentProps<typeof DialogPrimitive.Content> & { showCloseButton?: boolean }) {
  return (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn(
          'bg-card text-card-foreground data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 fixed top-1/2 left-1/2 z-50 grid w-full max-w-[calc(100%-2rem)] -translate-x-1/2 -translate-y-1/2 gap-4 rounded-xl border p-4 shadow-lg sm:max-w-sm',
          className,
        )}
        {...props}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            className="ring-offset-background focus-visible:ring-ring absolute top-3 right-3 cursor-pointer rounded-sm opacity-60 transition-opacity hover:opacity-100 focus-visible:ring-2 focus-visible:outline-none"
          >
            <XIcon className="size-4" />
            <span className="sr-only">Close</span>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  );
}

function DialogHeader({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="dialog-header"
      className={cn('flex flex-col gap-1 text-left', className)}
      {...props}
    />
  );
}

function DialogFooter({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn('flex flex-col-reverse gap-2 sm:flex-row sm:justify-end', className)}
      {...props}
    />
  );
}

function DialogTitle({ className, ...props }: ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn('text-base leading-none font-semibold', className)}
      {...props}
    />
  );
}

function DialogDescription({
  className,
  ...props
}: ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn('text-muted-foreground text-sm', className)}
      {...props}
    />
  );
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
};

import type { Direction } from './types';

/**
 * Formatting helpers. Every number shown in a trading UI is formatted the same
 * way twice: fixed decimals so digits line up in a tabular-nums column, and an
 * explicit sign where direction matters.
 */

const cache = new Map<string, Intl.NumberFormat>();

function nf(min: number, max: number, extra?: Intl.NumberFormatOptions) {
  const key = `${min}:${max}:${extra ? JSON.stringify(extra) : ''}`;
  let f = cache.get(key);
  if (!f) {
    f = new Intl.NumberFormat('en-US', {
      minimumFractionDigits: min,
      maximumFractionDigits: max,
      ...extra,
    });
    cache.set(key, f);
  }
  return f;
}

/** `1234.5` at precision 2 -> `"1,234.50"`. */
export function formatPrice(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  return nf(precision, precision).format(value);
}

/** Quantity: grouped, trailing zeros trimmed. */
export function formatQuantity(value: number, precision = 0): string {
  if (!Number.isFinite(value)) return '--';
  return nf(0, precision).format(value);
}

/** `1250000` -> `"1.25M"`. Keeps size columns to four glyphs. */
export function formatCompact(value: number, digits = 2): string {
  if (!Number.isFinite(value)) return '--';
  const abs = Math.abs(value);
  const sign = value < 0 ? '-' : '';
  const units: Array<[number, string]> = [
    [1e12, 'T'],
    [1e9, 'B'],
    [1e6, 'M'],
    [1e3, 'K'],
  ];
  for (const [scale, suffix] of units) {
    if (abs >= scale) {
      const scaled = abs / scale;
      // Keep three significant digits: 1.25M, 12.5M, 125M.
      const d = scaled >= 100 ? 0 : scaled >= 10 ? 1 : digits;
      return `${sign}${nf(0, d).format(scaled)}${suffix}`;
    }
  }
  return `${sign}${nf(0, abs < 1 ? digits : 0).format(abs)}`;
}

/** `0.0421` -> `"+4.21%"`. Input is a ratio, not percentage points. */
export function formatPercent(ratio: number, precision = 2, signed = true): string {
  if (!Number.isFinite(ratio)) return '--';
  const pct = ratio * 100;
  const sign = signed && pct > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(pct)}%`;
}

/** Absolute change with a forced sign so gains and losses align. */
export function formatSigned(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(value)}`;
}

/** `hh:mm:ss` in local time - the tape's only useful resolution. */
export function formatTime(time: number | Date, withMillis = false): string {
  const d = time instanceof Date ? time : new Date(time);
  const base = d.toTimeString().slice(0, 8);
  if (!withMillis) return base;
  return `${base}.${String(d.getMilliseconds()).padStart(3, '0')}`;
}

/** Axis-friendly timestamp: drops seconds, adds the date when it changes. */
export function formatAxisTime(time: number, showDate = false): string {
  const d = new Date(time);
  const hhmm = d.toTimeString().slice(0, 5);
  if (!showDate) return hhmm;
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

/** Signed money, e.g. `-$1,204.50`. */
export function formatMoney(value: number, currency = '$', precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value < 0 ? '-' : '';
  return `${sign}${currency}${nf(precision, precision).format(Math.abs(value))}`;
}

/** Direction of `value` relative to `reference` (default zero). */
export function directionOf(value: number, reference = 0): Direction {
  if (!Number.isFinite(value) || value === reference) return 'flat';
  return value > reference ? 'up' : 'down';
}

/** The `tu-up` / `tu-down` / `tu-flat` class for a direction. */
export function directionClass(direction: Direction): string {
  return `tu-${direction}`;
}

/** `+` / `-` glyphs used by DeltaBadge and the tape. */
export function directionArrow(direction: Direction): string {
  return direction === 'up' ? '▲' : direction === 'down' ? '▼' : '–';
}

/** Round to the instrument's tick so UI-entered prices are always valid. */
export function roundToTick(price: number, tickSize: number): number {
  if (!tickSize || tickSize <= 0) return price;
  const ticks = Math.round(price / tickSize);
  // Re-round after dividing to shake off float dust (0.1 * 3 = 0.30000000000000004).
  const decimals = decimalsOf(tickSize);
  return Number((ticks * tickSize).toFixed(decimals));
}

/** Decimal places implied by a tick size: `0.01` -> 2, `0.5` -> 1, `5` -> 0. */
export function decimalsOf(tickSize: number): number {
  if (!Number.isFinite(tickSize) || tickSize <= 0) return 2;
  const s = tickSize.toString();
  if (s.includes('e-')) return Number(s.split('e-')[1]);
  const dot = s.indexOf('.');
  return dot === -1 ? 0 : s.length - dot - 1;
}

/** Shared domain types. Deliberately plain so any feed can map onto them. */

export type Side = 'buy' | 'sell';
export type Direction = 'up' | 'down' | 'flat';

/** One OHLCV bar. `time` is epoch milliseconds at the bar's open. */
export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

/** A single price level in the book. */
export interface BookLevel {
  price: number;
  size: number;
}

export interface OrderBookSnapshot {
  /** Highest price first. */
  bids: BookLevel[];
  /** Lowest price first. */
  asks: BookLevel[];
}

export interface Trade {
  id: string;
  time: number;
  price: number;
  size: number;
  /** Aggressor side: `buy` means it lifted the offer. */
  side: Side;
}

export interface Quote {
  symbol: string;
  name?: string;
  last: number;
  /** Previous session close, used for the day change. */
  prevClose: number;
  bid?: number;
  ask?: number;
  dayHigh?: number;
  dayLow?: number;
  volume?: number;
  /** Optional intraday series for an inline sparkline. */
  history?: number[];
}

export interface Position {
  symbol: string;
  /** Signed: negative is short. */
  quantity: number;
  avgPrice: number;
  markPrice: number;
}

export type OrderType = 'market' | 'limit' | 'stop' | 'stop-limit';
export type OrderStatus = 'working' | 'filled' | 'partial' | 'cancelled' | 'rejected';

export interface OrderDraft {
  symbol: string;
  side: Side;
  type: OrderType;
  quantity: number;
  /** Required for limit / stop-limit. */
  limitPrice?: number;
  /** Required for stop / stop-limit. */
  stopPrice?: number;
  timeInForce: TimeInForce;
}

export type TimeInForce = 'day' | 'gtc' | 'ioc' | 'fok';

export interface Order extends OrderDraft {
  id: string;
  time: number;
  status: OrderStatus;
  filledQuantity: number;
  avgFillPrice?: number;
}

/** Price/size formatting rules for an instrument. */
export interface Instrument {
  symbol: string;
  name?: string;
  /** Decimal places for price. */
  pricePrecision: number;
  /** Minimum price increment. */
  tickSize: number;
  /** Decimal places for quantity. */
  sizePrecision?: number;
  /** Quote-currency symbol, e.g. "$". */
  currency?: string;
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge Tailwind classes with later ones winning - the same `cn` shadcn/ui
 * uses, so a consumer can override any class on any component by passing
 * `className`, with no specificity war.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
